import { test, expect } from '@playwright/test';

test.describe('Recently Searched Terms Suggestions', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('http://localhost:3000');
  });

  test('should display recently searched terms as suggestions', async ({ page }) => {
    // Perform first search
    const searchInput = page.getByRole('searchbox');
    await searchInput.fill('playwright');
    await searchInput.press('Enter');
    await page.waitForLoadState('networkidle');

    // Go back to search
    await page.goto('http://localhost:3000');

    // Click on search input to trigger suggestions
    await searchInput.click();

    // Verify recently searched term appears in suggestions
    const suggestion = page.getByText('playwright', { exact: false });
    await expect(suggestion).toBeVisible();
  });

  test('should show multiple recently searched terms', async ({ page }) => {
    const searchInput = page.getByRole('searchbox');

    // Perform multiple searches
    const searchTerms = ['automation', 'testing', 'qa'];

    for (const term of searchTerms) {
      await searchInput.fill(term);
      await searchInput.press('Enter');
      await page.waitForLoadState('networkidle');
      await page.goto('http://localhost:3000');
    }

    // Click on search input to show suggestions
    await searchInput.click();

    // Verify all recently searched terms appear
    for (const term of searchTerms) {
      const suggestion = page.getByText(term, { exact: false });
      await expect(suggestion).toBeVisible();
    }
  });

  test('should allow selecting a suggestion from recently searched terms', async ({ page }) => {
    const searchInput = page.getByRole('searchbox');

    // Perform initial search
    await searchInput.fill('typescript');
    await searchInput.press('Enter');
    await page.waitForLoadState('networkidle');

    // Go back to search
    await page.goto('http://localhost:3000');

    // Click on search input
    await searchInput.click();

    // Click on the suggestion
    const suggestion = page.getByText('typescript', { exact: false });
    await suggestion.click();

    // Verify search was performed with the selected suggestion
    await page.waitForLoadState('networkidle');
    await expect(searchInput).toHaveValue('typescript');
  });

  test('should clear recently searched terms when user clears history', async ({ page }) => {
    const searchInput = page.getByRole('searchbox');

    // Perform a search
    await searchInput.fill('history');
    await searchInput.press('Enter');
    await page.waitForLoadState('networkidle');

    // Go back to search
    await page.goto('http://localhost:3000');

    // Find and click clear history button if it exists
    const clearButton = page.getByRole('button', { name: /clear/i });
    if (await clearButton.isVisible()) {
      await clearButton.click();
    }

    // Click on search input
    await searchInput.click();

    // Verify the suggestion is no longer visible
    const suggestion = page.getByText('history', { exact: false });
    await expect(suggestion).not.toBeVisible();
  });
});
